/**
 * 金手指配置（运行时可变，与 localStorage 同步）
 * 供游戏内"金手指面板"和游戏逻辑共同使用。
 */
export type CheatValue = boolean | number | null;

export interface CheatDef {
  key: string;
  label: string;
  kind: "toggle" | "choice";
  options?: CheatValue[];
  optionLabels?: string[];
  def: CheatValue;
  /** 只在"新开一局"时生效 */
  newRunOnly?: boolean;
}

export const CHEAT_DEFS: CheatDef[] = [
  { key: "XP_MULTIPLIER_OVERRIDE", label: "经验倍率", kind: "choice", options: [1, 2, 5, 10, 50, 100], def: 10 },
  { key: "CRITICAL_HIT_OVERRIDE", label: "必定暴击", kind: "toggle", def: true },
  { key: "SHINY_OVERRIDE", label: "全部闪光", kind: "toggle", def: true },
  { key: "HAS_PASSIVE_ABILITY_OVERRIDE", label: "自带隐藏特性", kind: "toggle", def: true },
  {
    key: "IVS_OVERRIDE",
    label: "个体值",
    kind: "choice",
    options: [null, 15, 31],
    optionLabels: ["默认", "中等", "全满"],
    def: 31,
  },
  { key: "WAIVE_SHOP_FEES_OVERRIDE", label: "商店免费", kind: "toggle", def: true },
  { key: "WAIVE_ROLL_FEE_OVERRIDE", label: "重掷免费", kind: "toggle", def: true },
  { key: "FREE_CANDY_UPGRADE_OVERRIDE", label: "糖果升级免费", kind: "toggle", def: true },
  {
    key: "LEVEL_CAP_OVERRIDE",
    label: "等级上限",
    kind: "choice",
    options: [0, 100, -1],
    optionLabels: ["按波次", "100", "无限制"],
    def: -1,
  },
  {
    key: "STARTING_LEVEL_OVERRIDE",
    label: "开局等级",
    kind: "choice",
    options: [0, 5, 10, 20, 50],
    optionLabels: ["默认", "5", "10", "20", "50"],
    def: 20,
    newRunOnly: true,
  },
  {
    key: "STARTING_MONEY_OVERRIDE",
    label: "开局金钱",
    kind: "choice",
    options: [0, 1000, 10000, 99999],
    optionLabels: ["默认", "1000", "1万", "99999"],
    def: 99999,
    newRunOnly: true,
  },
  { key: "EGG_FREE_GACHA_PULLS_OVERRIDE", label: "抽卡不消耗券", kind: "toggle", def: false },
  { key: "UNLIMITED_EGG_COUNT_OVERRIDE", label: "解除99蛋上限", kind: "toggle", def: true },
  { key: "VOUCHER_MULTIPLIER", label: "扭蛋券倍率", kind: "choice", options: [1, 2, 5, 10, 50], def: 10 },
  { key: "VOUCHER_PREMIUM_ONLY", label: "Boss 只掉高级券", kind: "toggle", def: true },
];

const STORAGE_KEY = "pgCheats";

const values: Record<string, CheatValue> = {};
for (const d of CHEAT_DEFS) {
  values[d.key] = d.def;
}

/** 从 localStorage 读回玩家保存的配置 */
export function loadSavedCheats(): void {
  try {
    const raw = globalThis.localStorage?.getItem(STORAGE_KEY);
    if (!raw) {
      return;
    }
    const obj = JSON.parse(raw) as Record<string, CheatValue>;
    for (const d of CHEAT_DEFS) {
      if (Object.hasOwn(obj, d.key)) {
        values[d.key] = obj[d.key];
      }
    }
  } catch {}
}

export function getCheatValue(key: string): CheatValue {
  return values[key];
}

/** 读取某个金手指数值（带兜底） */
export function getCheat<T extends CheatValue>(key: string, fallback: T): T {
  const v = values[key];
  return (v === undefined || v === null ? (fallback as CheatValue) : v) as T;
}

export function setCheatValue(key: string, value: CheatValue): void {
  values[key] = value;
}

export function saveCheats(): void {
  try {
    globalThis.localStorage?.setItem(STORAGE_KEY, JSON.stringify(values));
  } catch {}
}

/** 把配置写进 activeOverrides（对象可变，游戏逻辑会实时读取） */
export function applyCheats(overrides: Record<string, unknown>): void {
  for (const d of CHEAT_DEFS) {
    if (d.key.endsWith("_OVERRIDE")) {
      overrides[d.key] = values[d.key];
    }
  }
}
